/** The authority letters in rank order (`D` lowest). */
export const AUTHORITY_ORDER = ['D', 'F', 'G', 'H', 'J', 'L', 'M', 'N', 'O', 'P', 'Z'] as const;

/** `true` when letter `a` is at least letter `min` (the legacy numeric comparison). */
export function authorityAtLeast(a: string, min: string): boolean {
  return a.charCodeAt(0) >= min.charCodeAt(0);
}

export function isCap(name: string): name is Cap {
  return (CAPS as readonly string[]).includes(name);
}
